/// <summary>
/// Dialog to create the <c>METTariffItemCodeBase</c> and <c>METTariffItemCode</c>
/// </summary>
public class METItemTariffCreate extends Runbase
{
    DialogField fieldTariffItem;
    DialogField fieldStatCode;
    DialogField fieldCustomsExcise;
    DialogField fieldDescription;

    DialogField fieldBeerAllowance;
    DialogField fieldStrengthLessOrEqual;
    DialogField fieldStrengthGreaterThan;
    DialogField fieldAdValoremOrBeerSubsidyRate;
    DialogField fieldDutyLAL;
    DialogField fieldValidFrom;

    METTariffItem                   tariffItem;
    METStatCode                     statCode;
    METCustomExcise                 customExcise;
    Description                     description;

    METBeerAllowance                beerAllowance;
    METStrengthLessOrEqual          strengthLessOrEqual;
    METStrengthGreaterThan          strengthGreaterThan;
    METAdValoremOrBeerSubsidyRate   adValoremOrBeerSubsidyRate;
    METDutyLAL                      dutyLAL;
    ValidFromDate                   validFromDate;

    METTariffItemCodeBase   tariffItemCodeBase;
    METTariffItemCode       tariffItemCode;


}

Method.Source:
    /// <summary>
    /// Creates the dialog control with required fields
    /// </summary>
    /// <returns>Dialog object</returns>
    public Object dialog()
    {
        DialogRunbase dialog;
    
        dialog = super();

        //Fields for item code base
        fieldCustomsExcise = dialog.addFieldValue(EnumStr(METCustomExcise), customExcise);
        fieldStatCode = dialog.addFieldValue(extendedTypeStr(METStatCode), statCode);
        fieldTariffItem = dialog.addFieldValue(extendedTypeStr(METTariffItem), tariffItem); 
        fieldDescription = dialog.addFieldValue(extendedTypeStr(Description), description);
        
        fieldCustomsExcise.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METItemTariffCreate, customExcise_modified), this);
        fieldTariffItem.mandatory_RU(true);
        fieldDescription.mandatory_RU(true);

        //fields for tariff item code
        fieldBeerAllowance = dialog.addFieldValue(extendedTypeStr(METBeerAllowance), beerAllowance);
        fieldStrengthLessOrEqual = dialog.addFieldValue(extendedTypeStr(METStrengthLessOrEqual), strengthLessOrEqual);
        fieldStrengthGreaterThan = dialog.addFieldValue(extendedTypeStr(METStrengthGreaterThan), strengthGreaterThan);
        fieldAdValoremOrBeerSubsidyRate = dialog.addFieldValue(extendedTypeStr(METAdValoremOrBeerSubsidyRate), adValoremOrBeerSubsidyRate);
        fieldDutyLAL = dialog.addFieldValue(extendedTypeStr(METDutyLAL), dutyLAL);
        fieldValidFrom = dialog.addFieldValue(extendedTypeStr(ValidFromDate), validFromDate);

        return dialog;
    }

    /// <summary>
    /// Retreive the data from input dialog
    /// </summary>
    /// <returns>Return true if input data retreived successfully. otherwise false</returns>
    public boolean getFromDialog()
    {
        boolean ret;
    
        ret = super();

        customExcise = fieldCustomsExcise.value();
        statCode     = fieldStatCode.value();
        tariffItem   = fieldTariffItem.value();
        description  = fieldDescription.value();

        beerAllowance               = fieldBeerAllowance.value();
        strengthLessOrEqual         = fieldStrengthLessOrEqual.value();
        strengthGreaterThan         = fieldStrengthGreaterThan.value();
        adValoremOrBeerSubsidyRate  = fieldAdValoremOrBeerSubsidyRate.value();
        dutyLAL                     = fieldDutyLAL.value();
        validFromDate               = fieldValidFrom.value();
    
        return ret;
    }

    /// <summary>
    /// Validates the dialog input before processing
    /// </summary>
    /// <param name = "calledFrom">Caller object</param>
    /// <returns>True if the inputs are valid. Otherwise false</returns>
    public boolean validate(Object calledFrom = null)
    {
        boolean ret;
    
        ret = super(calledFrom);

        if(validFromDate == dateNull())
        {
            ret = checkFailed(strFmt("@SYS84753", fieldPName(METTariffItemCode, validFrom)));
        }

        if (validFromDate > DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
        {
            ret = checkFailed(strFmt("@MET:DateCannotFutureDate", fieldPName(METTariffItemCode, validFrom)));
        }

        if(!tariffItem)
        {
            ret = checkFailed(strFmt("@SYS84753", fieldPName(METTariffItemCodeBase, TariffItem)));
        }

        if(!description)
        {
            ret = checkFailed(strFmt("@SYS84753", fieldPName(METTariffItemCodeBase, Description)));
        }

        if(!fieldCustomsExcise.value())
        {
            ret = checkFailed(strFmt("@SYS84753", fieldPName(METTariffItemCodeBase, CustomsExcise)));
        }
    
        return ret;
    }

    /// <summary>
    /// The modified event of the CustomExcise dialog control
    /// </summary>
    /// <param name = "_control">Dialog control</param>
    /// <returns></returns>
    private boolean customExcise_modified(FormComboboxControl _control)
    {
        boolean ret  = true;
        customExcise = fieldCustomsExcise.value();

        if(customExcise == METCustomExcise::C)
        {
            fieldStatCode.value(METConstants::emptyString);
            fieldStatCode.allowEdit(true);
            fieldStatCode.mandatory_RU(true);
            
        }
        else if(customExcise == METCustomExcise::E)
        {
            fieldStatCode.value("@MET:DefaultStatCodeText");
            fieldStatCode.allowEdit(false);
        }
        else
        {
            fieldStatCode.allowEdit(true);
        }

        return ret;
    }

    /// <summary>
    /// Main operation of the class to create the tariff item code
    /// </summary>
    public void run()
    {
        try
        {
            ttsbegin;
            tariffItemCodeBase.clear();
            tariffItemCodeBase.initValue();

            tariffItemCodeBase.TariffItem = tariffItem;
            tariffItemCodeBase.StatCode = statCode;
            tariffItemCodeBase.Description = description;
            tariffItemCodeBase.CustomsExcise = customExcise;
            tariffItemCodeBase.NAT3040 = (customExcise == METCustomExcise::C) ?  METNAT3040::NAT30 : METNAT3040::NAT40;

            if(tariffItemCodeBase.validateWrite())
            {
                tariffItemCodeBase.insert();
            }

            if(tariffItemCodeBase.RecId)
            {
                tariffItemCode.clear();
                tariffItemCode.initValue();
                tariffItemCode.METTariffItemCodeBase = tariffItemCodeBase.RecId;
                tariffItemCode.BeerAllowance = beerAllowance;
                tariffItemCode.StrengthLessOrEqual = strengthLessOrEqual;
                tariffItemCode.StrengthGreaterThan = strengthGreaterThan;
                tariffItemCode.AdValoremOrBeerSubsidyRate = adValoremOrBeerSubsidyRate;
                tariffItemCode.DutyLAL = dutyLAL;
                tariffItemCode.ValidFrom = validFromDate;
                tariffItemCode.ValidTo = dateMax();

                if (tariffItemCode.validateWrite())
                {
                    tariffItemCode.insert();
                }
                else
                {
                    tariffItemCodeBase.delete();
                }
            }
            ttscommit;
        }
        catch (Exception::Error)
        {
            Error("@MET:TariffItemCodeCreateErrorMsg");
        }
    }

/// <summary>
/// Gets or sets the <c>METTariffItemCodeBase</c> record
/// </summary>
/// <param name = "_tariffItemCodeBase">Record buffer</param>
/// <returns>Record buffer</returns>
public METTariffItemCodeBase parmTariffItemCodeBase(METTariffItemCodeBase _tariffItemCodeBase = tariffItemCodeBase)
{
    tariffItemCodeBase = _tariffItemCodeBase;
    return tariffItemCodeBase;
}
